<template><ToolShell :eyebrow="label('DNS-only check', 'Comprobación solo DNS')" :title="label('Review domain readiness', 'Revisa la preparación del dominio')" :description="label('Klyrow checks MX, SPF and DMARC through bounded DNS lookups. It never fetches the website or probes private networks.', 'Klyrow comprueba MX, SPF y DMARC mediante consultas DNS limitadas. Nunca descarga el sitio ni explora redes privadas.')"><form class="stack" @submit.prevent="run"><BaseInput id="domain-readiness" v-model="domain" name="domain" :label="label('Domain name', 'Nombre de dominio')" placeholder="example.com" required /><BaseButton type="submit" :disabled="pending">{{ pending ? label('Checking…', 'Comprobando…') : label('Check DNS', 'Comprobar DNS') }}</BaseButton><BaseAlert v-if="errorMessage" tone="danger">{{ errorMessage }}</BaseAlert><div v-if="result" class="stack results"><BaseAlert :tone="result.status === 'ready_for_review' ? 'success' : 'warning'">{{ result.domain }} — {{ result.status }}</BaseAlert><div class="grid"><BaseCard v-for="(check,key) in result.checks" :key="key"><h3>{{ String(key).toUpperCase() }}</h3><p>{{ check.status }}</p><code v-if="'record' in check && check.record">{{ check.record }}</code><p v-if="'guidance' in check">{{ check.guidance }}</p></BaseCard></div><p class="fine-print">{{ result.disclaimer }}</p></div></form></ToolShell></template>
<script setup lang="ts">interface Check {status:string;record?:string;guidance?:string} interface Result{domain:string;status:string;checks:Record<string,Check>;disclaimer:string} const {locale}=useLocale();const label=(en:string,es:string)=>locale.value==='es'?es:en;const domain=ref('');const result=ref<Result>();const{pending,errorMessage,execute}=useToolRequest();const run=async()=>{result.value=await execute<Result>('/api/v1/tools/domain-readiness',{domain:domain.value})}</script>
<style scoped>.results code{display:block;overflow-wrap:anywhere}.fine-print{color:var(--text-secondary);font-size:.88rem}</style>
